printf "import test from 'node:test';
import assert from 'node:assert/strict';
import { dashboard } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('dashboard with empty invoices', () => {
  const result = dashboard([], '2024-12-31');
  assert.deepEqual(result.counts, { draft: 0, issued: 0, partially_paid: 0, paid: 0 });
  assert.equal(result.outstanding, 0);
  assert.equal(result.overdue.count, 0);
  assert.equal(result.overdue.amount, 0);
  assert.deepEqual(result.topCustomers, []);
});

test('dashboard counts invoices by status', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(draft, []).value;
  const paid = recordPayment(issued, { amount: 114950, date: '2024-01-20' }).value;

  const result = dashboard([draft, issued, paid], '2024-12-31');
  assert.equal(result.counts.draft, 1);
  assert.equal(result.counts.issued, 1);
  assert.equal(result.counts.paid, 1);
});

test('dashboard calculates outstanding', () => {
  const invoice1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(invoice1, []).value;

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(invoice2, ['INV-2024-0001']).value;
  const partial = recordPayment(issued2, { amount: 50000, date: '2024-01-25' }).value;

  const result = dashboard([issued1, partial], '2024-12-31');
  const inv1Total = 114950;
  const inv2Remaining = 114950 - 50000;
  const expected = inv1Total + inv2Remaining;
  assert.equal(result.outstanding, expected);
});

test('dashboard excludes paid invoices from outstanding', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;
  const issued = issueInvoice(invoice, []).value;
  const paid = recordPayment(issued, { amount: 114950, date: '2024-01-20' }).value;

  const result = dashboard([paid], '2024-12-31');
  assert.equal(result.outstanding, 0);
});

test('dashboard overdue count and amount', () => {
  const invoice1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;
  const issued1 = issueInvoice(invoice1, []).value;

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-12-20',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET30',
  }).value;
  const issued2 = issueInvoice(invoice2, ['INV-2024-0001']).value;

  const result = dashboard([issued1, issued2], '2024-12-31');
  assert.equal(result.overdue.count, 1);
  assert.equal(result.overdue.amount, 114950);
});

test('dashboard top customers by due amount', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2024-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-004',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2024-0001', 'INV-2024-0002']).value;

  const result = dashboard([issued1, issued2, issued3], '2024-12-31');
  assert.equal(result.topCustomers.length, 3);
  assert.equal(result.topCustomers[0].customerId, 'C-002');
  assert.equal(result.topCustomers[1].customerId, 'C-003');
  assert.equal(result.topCustomers[2].customerId, 'C-004');
});

test('dashboard returns only top 3 customers', () => {
  const invoices = [];
  for (let i = 0; i < 5; i++) {
    const inv = createInvoice({
      customerId: \`C-\${String(i + 1).padStart(3, '0')}\`,
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: i + 1 }],
    }).value;
    const issued = issueInvoice(inv, invoices.map(inv => inv.number || 'DRAFT')).value;
    invoices.push(issued);
  }

  const result = dashboard(invoices, '2024-12-31');
  assert.equal(result.topCustomers.length, 3);
});

test('dashboard excludes draft invoices from outstanding and top customers', () => {
  const draft = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;
  const issuedInv = issueInvoice(issued, []).value;

  const result = dashboard([draft, issuedInv], '2024-12-31');
  assert.equal(result.outstanding, 114950);
  assert.equal(result.topCustomers.length, 1);
  assert.equal(result.topCustomers[0].customerId, 'C-003');
});

test('dashboard top customers sorted by due amount descending', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2024-0001']).value;

  const inv3 = createInvoice({
    customerId: 'C-004',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;
  const issued3 = issueInvoice(inv3, ['INV-2024-0001', 'INV-2024-0002']).value;

  const result = dashboard([issued1, issued2, issued3], '2024-12-31');
  assert.ok(result.topCustomers[0].due >= result.topCustomers[1].due);
  assert.ok(result.topCustomers[1].due >= result.topCustomers[2].due);
});

test('dashboard aggregates multiple invoices per customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;
  const issued2 = issueInvoice(inv2, ['INV-2024-0001']).value;

  const result = dashboard([issued1, issued2], '2024-12-31');
  const customer = result.topCustomers.find(c => c.customerId === 'C-002');
  assert.ok(customer);
  assert.equal(customer.due, 114950 * 2);
});
